def resolve(path, cwd, links):
    # Validate cwd is canonical absolute path
    if not isinstance(cwd, str) or not cwd.startswith('/'):
        return None

    # Determine the starting path
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]
    else:
        current = cwd
        components = path.split('/')

    link_count = 0

    while components:
        component = components.pop(0)

        # Skip empty components and '.'
        if not component or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
            continue

        # Append component to current path
        if current == '/':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if candidate is a symlink
        if candidate in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[candidate]

            # Resolve target components
            if target.startswith('/'):
                current = '/'
                target_components = target.split('/')[1:]
            else:
                # Target is relative to the directory containing the link
                if candidate == '/':
                    current = '/'
                else:
                    current = candidate.rsplit('/', 1)[0]
                    if not current:
                        current = '/'
                target_components = target.split('/')

            # Prepend remaining components to process
            components = target_components + components
        else:
            current = candidate

    # Return result without trailing slash, except for '/'
    if current == '/':
        return '/'
    else:
        return current

